package in.aicon.pocket;
import java.util.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class BarrierRemoteTest {
 static class Remote implements BarrierRemote.Transport {Map<String,String> markers=new LinkedHashMap<>(),files=new LinkedHashMap<>();int next;String resetDuringAppend;public Map<String,String> resetMarkers(){return new LinkedHashMap<>(markers);}public Map<String,String> operationFiles(){return new LinkedHashMap<>(files);}public String reserveFileId(){return "file_"+(++next);}public void appendFile(String id,String body)throws Exception{if(resetDuringAppend!=null)markers.put("reset_race",ResetWire.marker(resetDuringAppend));String old=files.putIfAbsent(id,body);if(old!=null&&!old.equals(body))throw new IllegalArgumentException("collision");}public void deleteOperationFile(String id){files.remove(id);}}
 SyncEngine.Pending pending(String file){String id=UUID.randomUUID().toString();return new SyncEngine.Pending(UUID.randomUUID().toString(),file,new SyncModel.Record(id,"private money",false,Collections.singletonMap("device",1L)));}
 @Test public void appendInFlightAtResetNeverReturnsAfterBarrierAcknowledgment()throws Exception{Remote raw=new Remote();ResetBarrier.View initial=new ResetBarrier.View(Collections.emptySet());BarrierRemote before=new BarrierRemote(raw,initial);SyncEngine.Pending op=pending("file_before");raw.resetDuringAppend=UUID.randomUUID().toString();before.append(op);assertEquals(1,raw.files.size());ResetBarrier.View after=null;try{before.pull();fail();}catch(BarrierRemote.ResetObserved event){assertTrue(event.check.resetObserved);after=event.check.remote;}assertNotNull(after);assertTrue(new BarrierRemote(raw,after).pull().isEmpty());}
 @Test public void missingResetHistoryAndUnknownDeletionStopBeforeEffects()throws Exception{Remote raw=new Remote();String reset=UUID.randomUUID().toString();BarrierRemote after=new BarrierRemote(raw,new ResetBarrier.View(Collections.singleton(reset)));try{after.append(pending("file_a"));fail();}catch(IllegalStateException expected){}assertTrue(raw.files.isEmpty());raw.markers.put("marker",ResetWire.marker(reset));after.pull();try{after.deleteContentFile("uninspected");fail();}catch(IllegalArgumentException expected){}assertTrue(raw.files.isEmpty());}
 @Test public void futureBarrierOperationForcesRecheckInsteadOfSilentDrop()throws Exception{Remote raw=new Remote();ResetBarrier.View initial=new ResetBarrier.View(Collections.emptySet()),future=initial.reset(UUID.randomUUID().toString());raw.files.put("file_a",ResetWire.operation(pending("file_a"),future));try{new BarrierRemote(raw,initial).pull();fail();}catch(IllegalStateException expected){}assertEquals(1,raw.files.size());}
 @Test public void wireRejectsHiddenPayloadInMarkerAndDuplicateBarrierIds()throws Exception{String reset=UUID.randomUUID().toString();JSONObject bad=new JSONObject(ResetWire.marker(reset)).put("payload","money");try{ResetWire.parseMarker(bad.toString());fail();}catch(IllegalArgumentException expected){}JSONArray ids=new JSONArray().put(reset).put(reset);try{ResetWire.parseIds(ids);fail();}catch(IllegalArgumentException expected){}assertFalse(ResetWire.marker(reset).contains("money"));}
 @Test public void retiredLateUploadIsScrubbedOnNextSuccessfulSyncCycle()throws Exception{Remote raw=new Remote();ResetBarrier.View before=new ResetBarrier.View(Collections.emptySet()),after=before.reset(UUID.randomUUID().toString());for(String reset:after.known)raw.markers.put("marker",ResetWire.marker(reset));raw.files.put("late_file",ResetWire.operation(pending("late_file"),before));raw.files.put("new_file",ResetWire.operation(pending("new_file"),after));BarrierRemote current=new BarrierRemote(raw,after);assertEquals(1,current.pull().size());assertEquals(1,current.cleanupRetired());assertFalse(raw.files.containsKey("late_file"));assertTrue(raw.files.containsKey("new_file"));assertEquals(1,raw.markers.size());}

}
